line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"You have excellent aim!\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"I need backup!\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"I never liked her.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"These things happen.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"That was nobody's fault.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"She was provoking you.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Oh dear.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Oh my!\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"I blame myself.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"He probably deserved it.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"I saw it.  It was an accident.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"She's probably okay.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Noted.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"But I need to protect the humans!\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"We're back!\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Hi there!\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Back again!\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Well, hello, stranger!\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"This time is OUR time.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Second time's a charm…\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Howdy, stranger!\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Thought you'd seen the last of us, didn't ya?\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Dang!\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"I thought we fixed that.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"What's a guy gotta got to do to get some bullets around here?\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Nope.  Still can't see.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Yep.  Still blind.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Click click click!  Still defective!\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Yeah, that's right!  Still defective!\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Yeah!  Still not working.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Yeah!  Non-lethal as ever.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Can't.  See.  A.  Thing.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Absolutely no improvement.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Not getting better with age!\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"This is just getting embarrassing.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Alright, you can go.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"[sigh] Don't tell anyone about this.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Well, I tried.  Best of luck!\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Hey, safe travels, there.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Hey, thanks so much!\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Don't be a stranger!\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"It's been a pleasure!\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"That was fun, wasn't it?\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"I can't see a thing.  What just happened?  Better open fire!  [click click click click]  Dang!\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"*clicking noises*\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"No, wait, wait!\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Hey, hold on now WHOA WHOA WHOA!\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Oh, this is ridiculous!\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Give me another channnnce!\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Hey!  Squeaky-voice!  Gimme some of your bullets!\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Can I get some bullets here?  Anybody got bullets?\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Uhhh, no bullets.  Sorry.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Shootin' blanks every time, ALL the time.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Standing down.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Watch and learn, everybody.  Watch and learn.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"So what am I, uh, supposed to do here?\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Identify yourself or I will shoot.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"Pleased to meetcha.\""), 30)
line({ "mon_turret", "mon_mi_go", "mon_mi_go_slaver" }, ccb.content.text("\"I'm gonna make you proud!\""), 30)

